  7	import com.pousada.marealta.dto.DocumentResponse;
  8	import com.pousada.marealta.dto.ReservationResponse;
  9	import com.pousada.marealta.model.Message;
 10	import com.pousada.marealta.model.Reservation;
 11	import com.pousada.marealta.model.Room;
 12	import com.pousada.marealta.repository.MessageRepository;
 13	import com.pousada.marealta.repository.RoomRepository;
 14	import com.pousada.marealta.service.DocumentService;
 15	import com.pousada.marealta.service.ReportService;
 16	import com.pousada.marealta.service.ReservationService;
 17	import io.javalin.Javalin;
 18	import io.javalin.http.Context;
 19	import org.slf4j.Logger;
 20	import org.slf4j.LoggerFactory;
 21	
 22	import java.math.BigDecimal;
 23	import java.sql.SQLException;
 24	import java.time.LocalDate;
 25	import java.time.YearMonth;
 26	import java.time.format.DateTimeFormatter;
 27	import java.util.HashMap;
 28	import java.util.List;
 29	import java.util.Map;
 30	
 31	public class Application {
 32	    private static final Logger logger = LoggerFactory.getLogger(Application.class);
 33	
 34	    public static void main(String[] args) throws SQLException {
 35	        DatabaseConfig.initialize();
 36	
 37	        String portStr = System.getenv("PORT");
 38	        int port = portStr != null && !portStr.isEmpty() ? Integer.parseInt(portStr) : 7070;
 39	
 40	        Javalin app = Javalin.create(config -> {
 41	            config.jsonMapper(new io.javalin.json.JsonMapper() {
 42	                private final ObjectMapper mapper = new ObjectMapper()
 43	                    .registerModule(new JavaTimeModule())
 44	                    .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
 45	
 46	                @Override
 47	                public String toJsonString(Object obj, java.lang.reflect.Type type) {
 48	                    try {
 49	                        return mapper.writeValueAsString(obj);
 50	                    } catch (Exception e) {
 51	                        throw new RuntimeException(e);
 52	                    }
 53	                }
 54	
 55	                @Override
 56	                public Object fromJsonString(String json, java.lang.reflect.Type targetType) {
 57	                    try {
 58	                        return mapper.readValue(json, mapper.constructType(targetType));
 59	                    } catch (Exception e) {
 60	                        throw new RuntimeException(e);
 61	                    }
 62	                }
 63	            });
 64	        });
 65	
 66	        // GET /rooms
 67	        app.get("/rooms", ctx -> {
 68	            try {
 69	                List<Room> rooms = RoomRepository.findAll();
 70	                List<Map<String, Object>> response = rooms.stream().map(r -> {
 71	                    Map<String, Object> map = new HashMap<>();
 72	                    map.put("number", r.getNumber());
 73	                    map.put("type", r.getType().name());
 74	                    map.put("capacity", r.getCapacity());
 75	                    map.put("nightlyRate", r.getNightlyRate());
 76	                    return map;
 77	                }).toList();
 78	                ctx.json(response);
 79	            } catch (SQLException e) {
 80	                sendError(ctx, 500, "DATABASE_ERROR", e.getMessage());
 81	            }
 82	        });
 83	
 84	        // POST /reservations
 85	        app.post("/reservations", ctx -> {
 86	            try {
 87	                Map<String, Object> body = ctx.bodyAsClass(Map.class);
 88	
 89	                Integer roomNumber = getIntValue(body, "roomNumber");
 90	                String guestName = getStringValue(body, "guestName");
 91	                String guestEmail = getStringValue(body, "guestEmail");
 92	                LocalDate checkIn = getDateValue(body, "checkIn");
 93	                LocalDate checkOut = getDateValue(body, "checkOut");
 94	                Integer guests = getIntValue(body, "guests");
 95	                String ratePlan = getStringValue(body, "ratePlan");
 96	                String guestCpf = getStringValue(body, "guestCpf");
 97	                String companyCnpj = getStringValue(body, "companyCnpj");
 98	                String companyName = getStringValue(body, "companyName");
 99	                String guestPassport = getStringValue(body, "guestPassport");
100	                String guestCountry = getStringValue(body, "guestCountry");
101	
102	                if (roomNumber == null || guestName == null || guestEmail == null ||
103	                    checkIn == null || checkOut == null || guests == null || ratePlan == null) {
104	                    sendError(ctx, 400, "INVALID_REQUEST", "Missing required fields");
105	                    return;
106	                }
107	
108	                Reservation reservation = ReservationService.createReservation(
109	                    roomNumber, guestName, guestEmail, checkIn, checkOut, guests, ratePlan,
110	                    guestCpf, companyCnpj, companyName, guestPassport, guestCountry
111	                );
112	
113	                ctx.status(201).json(ReservationResponse.from(reservation));
114	            } catch (IllegalArgumentException e) {
115	                handleServiceException(ctx, e);
116	            } catch (SQLException e) {
117	                sendError(ctx, 500, "DATABASE_ERROR", e.getMessage());
118	            } catch (Exception e) {
119	                sendError(ctx, 400, "INVALID_REQUEST", e.getMessage());
120	            }
121	        });
122	
123	        // GET /reservations/{id}
124	        app.get("/reservations/{id}", ctx -> {
125	            try {
126	                long id = Long.parseLong(ctx.pathParam("id"));
127	                Reservation reservation = ReservationService.getReservation(id);
128	                if (reservation == null) {
129	                    sendError(ctx, 404, "RESERVATION_NOT_FOUND", "Reservation not found");
130	                } else {
131	                    ctx.json(ReservationResponse.from(reservation));
132	                }
133	            } catch (SQLException e) {
134	                sendError(ctx, 500, "DATABASE_ERROR", e.getMessage());
135	            }
136	        });
137	
138	        // POST /reservations/{id}/confirmation
139	        app.post("/reservations/{id}/confirmation", ctx -> {
140	            try {
141	                long id = Long.parseLong(ctx.pathParam("id"));
142	                Map<String, Object> body = ctx.bodyAsClass(Map.class);
143	
144	                Object amountPaidObj = body.get("amountPaid");
145	                if (amountPaidObj == null) {
146	                    sendError(ctx, 400, "INVALID_REQUEST", "amountPaid is required");
147	                    return;
148	                }
149	
150	                BigDecimal amountPaid = new BigDecimal(amountPaidObj.toString());
151	                Reservation reservation = ReservationService.confirmReservation(id, amountPaid);
152	                ctx.json(ReservationResponse.from(reservation));
153	            } catch (IllegalArgumentException e) {
154	                handleServiceException(ctx, e);
155	            } catch (SQLException e) {
156	                sendError(ctx, 500, "DATABASE_ERROR", e.getMessage());
157	            } catch (Exception e) {
158	                sendError(ctx, 400, "INVALID_REQUEST", e.getMessage());
159	            }
160	        });
161	
162	        // POST /reservations/{id}/cancellation
163	        app.post("/reservations/{id}/cancellation", ctx -> {
164	            try {
165	                long id = Long.parseLong(ctx.pathParam("id"));
166	                Reservation reservation = ReservationService.cancelReservation(id);
167	                ctx.json(ReservationResponse.from(reservation));
168	            } catch (IllegalArgumentException e) {
169	                handleServiceException(ctx, e);
170	            } catch (SQLException e) {
171	                sendError(ctx, 500, "DATABASE_ERROR", e.getMessage());
172	            }
173	        });
174	
175	        // POST /reservations/{id}/check-in
176	        app.post("/reservations/{id}/check-in", ctx -> {
177	            try {
178	                long id = Long.parseLong(ctx.pathParam("id"));
179	                Reservation reservation = ReservationService.checkIn(id);
180	                ctx.json(ReservationResponse.from(reservation));
181	            } catch (IllegalArgumentException e) {
182	                handleServiceException(ctx, e);
183	            } catch (SQLException e) {
184	                sendError(ctx, 500, "DATABASE_ERROR", e.getMessage());
185	            }
186	        });
187	
188	        // POST /reservations/{id}/check-out
189	        app.post("/reservations/{id}/check-out", ctx -> {
190	            try {
191	                long id = Long.parseLong(ctx.pathParam("id"));
192	                Reservation reservation = ReservationService.checkOut(id);
193	                DocumentResponse doc = DocumentService.generateDocument(reservation);
194	                ctx.json(doc);
195	            } catch (IllegalArgumentException e) {
196	                handleServiceException(ctx, e);
197	            } catch (SQLException e) {
198	                sendError(ctx, 500, "DATABASE_ERROR", e.getMessage());
199	            }
200	        });
201	
202	        // GET /reservations/{id}/document
203	        app.get("/reservations/{id}/document", ctx -> {
204	            try {
205	                long id = Long.parseLong(ctx.pathParam("id"));
206	                Reservation reservation = ReservationService.getReservation(id);
207	                if (reservation == null) {
208	                    sendError(ctx, 404, "RESERVATION_NOT_FOUND", "Reservation not found");
209	                } else if (reservation.getStatus() == Reservation.Status.PENDING) {
210	                    sendError(ctx, 409, "OPERATION_NOT_ALLOWED", "Document only available for paid reservations");
211	                } else {
212	                    DocumentResponse doc = DocumentService.generateDocument(reservation);
213	                    ctx.json(doc);
214	                }
215	            } catch (SQLException e) {
216	                sendError(ctx, 500, "DATABASE_ERROR", e.getMessage());
217	            }
218	        });
219	
220	        // GET /messages
221	        app.get("/messages", ctx -> {
222	            try {
223	                List<Message> messages = MessageRepository.findAll();
224	                List<Map<String, Object>> response = messages.stream().map(m -> {
225	                    Map<String, Object> map = new HashMap<>();
226	                    map.put("id", m.getId());
227	                    map.put("channel", m.getChannel().name());
228	                    map.put("to", m.getTo());
229	                    map.put("subject", m.getSubject());
230	                    map.put("body", m.getBody());
231	                    return map;
232	                }).toList();
233	                ctx.json(response);
234	            } catch (SQLException e) {
235	                sendError(ctx, 500, "DATABASE_ERROR", e.getMessage());
236	            }
237	        });
238	
239	        // GET /reports/occupancy
240	        app.get("/reports/occupancy", ctx -> {
241	            try {
242	                String dateStr = ctx.queryParam("date");
243	                if (dateStr == null || dateStr.isEmpty()) {
244	                    sendError(ctx, 400, "INVALID_REQUEST", "date parameter is required");
245	                    return;
246	                }
247	                LocalDate date = LocalDate.parse(dateStr);
248	                String report = ReportService.getOccupancyReport(date);
249	                ctx.header("Content-Type", "text/csv; charset=utf-8");
250	                ctx.result(report);
251	            } catch (Exception e) {
252	                sendError(ctx, 400, "INVALID_REQUEST", e.getMessage());
253	            }
254	        });
255	
256	        // GET /reports/revenue
257	        app.get("/reports/revenue", ctx -> {
258	            try {
259	                String monthStr = ctx.queryParam("month");
260	                if (monthStr == null || monthStr.isEmpty()) {
261	                    sendError(ctx, 400, "INVALID_REQUEST", "month parameter is required");
262	                    return;
263	                }
264	                YearMonth month = YearMonth.parse(monthStr);
265	                String report = ReportService.getRevenueReport(month);
266	                ctx.header("Content-Type", "text/csv; charset=utf-8");
267	                ctx.result(report);
268	            } catch (Exception e) {
269	                sendError(ctx, 400, "INVALID_REQUEST", e.getMessage());
270	            }
271	        });
272	
273	        app.start(port);
274	        logger.info("Pousada Maré Alta API started on port {}", port);
275	    }
276	
277	    private static void handleServiceException(Context ctx, IllegalArgumentException e) {
278	        String message = e.getMessage();
279	        if (message.equals("ROOM_NOT_FOUND")) {
280	            sendError(ctx, 404, "ROOM_NOT_FOUND", "Room not found");
281	        } else if (message.equals("RESERVATION_NOT_FOUND")) {
282	            sendError(ctx, 404, "RESERVATION_NOT_FOUND", "Reservation not found");
283	        } else if (message.equals("ROOM_UNAVAILABLE")) {
284	            sendError(ctx, 409, "ROOM_UNAVAILABLE", "Room is not available for the selected dates");
285	        } else if (message.equals("OPERATION_NOT_ALLOWED")) {
286	            sendError(ctx, 409, "OPERATION_NOT_ALLOWED", "Operation not allowed for this reservation");
287	        } else if (message.equals("CAPACITY_EXCEEDED")) {
288	            sendError(ctx, 422, "CAPACITY_EXCEEDED", "Number of guests exceeds room capacity");
289	        } else {
290	            sendError(ctx, 400, "INVALID_REQUEST", message);
291	        }
292	    }
293	
294	    private static void sendError(Context ctx, int status, String code, String message) {
295	        ctx.status(status);
296	        Map<String, Object> error = new HashMap<>();
297	        error.put("error", code);
298	        error.put("message", message);
299	        ctx.json(error);
300	    }
301	
302	    private static Integer getIntValue(Map<String, Object> map, String key) {
303	        Object value = map.get(key);
304	        if (value == null) return null;
305	        if (value instanceof Integer) return (Integer) value;
306	        if (value instanceof Number) return ((Number) value).intValue();
307	        return null;
308	    }
309	
310	    private static String getStringValue(Map<String, Object> map, String key) {
311	        Object value = map.get(key);
312	        if (value == null) return null;
313	        return value.toString();
314	    }
315	
316	    private static LocalDate getDateValue(Map<String, Object> map, String key) {
317	        Object value = map.get(key);
318	        if (value == null) return null;
319	        if (value instanceof LocalDate) return (LocalDate) value;
320	        try {
321	            return LocalDate.parse(value.toString());
322	        } catch (Exception e) {
323	            return null;
324	        }
325	    }
326	}
327	package com.pousada.marealta.config;
328	
329	import com.zaxxer.hikari.HikariConfig;
330	import com.zaxxer.hikari.HikariDataSource;
331	import org.slf4j.Logger;
332	import org.slf4j.LoggerFactory;
333	
334	import java.sql.Connection;
335	import java.sql.SQLException;
336	
337	public class DatabaseConfig {
338	    private static final Logger logger = LoggerFactory.getLogger(DatabaseConfig.class);
339	    private static HikariDataSource dataSource;
340	
341	    public static void initialize() throws SQLException {
342	        String dbUrl = System.getenv("DB_URL");
343	        String dbUser = System.getenv("DB_USER");
344	        String dbPassword = System.getenv("DB_PASSWORD");
345	
346	        if (dbUrl == null || dbUrl.isEmpty()) {
347	            throw new RuntimeException("DB_URL environment variable is required");
348	        }
349	        if (dbUser == null || dbUser.isEmpty()) {
350	            throw new RuntimeException("DB_USER environment variable is required");
351	        }
352	        if (dbPassword == null || dbPassword.isEmpty()) {
353	            throw new RuntimeException("DB_PASSWORD environment variable is required");
354	        }
355	
356	        HikariConfig config = new HikariConfig();
357	        config.setJdbcUrl(dbUrl);
358	        config.setUsername(dbUser);
359	        config.setPassword(dbPassword);
360	        config.setMaximumPoolSize(10);
361	        config.setMinimumIdle(2);
362	        config.setConnectionTimeout(30000);
363	        config.setIdleTimeout(600000);
364	        config.setMaxLifetime(1800000);
365	
366	        dataSource = new HikariDataSource(config);
367	        logger.info("Database connection pool initialized");
368	
369	        initializeTables();
370	    }
371	
372	    public static Connection getConnection() throws SQLException {
373	        if (dataSource == null) {
374	            throw new RuntimeException("Database not initialized. Call DatabaseConfig.initialize() first.");
375	        }
376	        return dataSource.getConnection();
377	    }
378	
379	    public static void close() {
380	        if (dataSource != null) {
381	            dataSource.close();
382	            logger.info("Database connection pool closed");
383	        }
384	    }
385	
386	    private static void initializeTables() throws SQLException {
387	        try (Connection conn = getConnection()) {
388	            // Create rooms table
389	            conn.createStatement().execute(
390	                "CREATE TABLE IF NOT EXISTS rooms (" +
391	                "  number INTEGER PRIMARY KEY," +
392	                "  type VARCHAR(20) NOT NULL," +
393	                "  capacity INTEGER NOT NULL," +
394	                "  nightly_rate NUMERIC(10, 2) NOT NULL" +
395	                ")"
396	            );
397	
398	            // Create reservations table
399	            conn.createStatement().execute(
400	                "CREATE TABLE IF NOT EXISTS reservations (" +
401	                "  id BIGSERIAL PRIMARY KEY," +
402	                "  room_number INTEGER NOT NULL REFERENCES rooms(number)," +
403	                "  guest_name VARCHAR(255) NOT NULL," +
404	                "  guest_email VARCHAR(255) NOT NULL," +
405	                "  guest_cpf VARCHAR(20)," +
406	                "  company_cnpj VARCHAR(20)," +
407	                "  company_name VARCHAR(255)," +
408	                "  guest_passport VARCHAR(20)," +
409	                "  guest_country VARCHAR(100)," +
410	                "  check_in DATE NOT NULL," +
411	                "  check_out DATE NOT NULL," +
412	                "  guests INTEGER NOT NULL," +
413	                "  rate_plan VARCHAR(20) NOT NULL," +
414	                "  nights INTEGER NOT NULL," +
415	                "  subtotal NUMERIC(10, 2) NOT NULL," +
416	                "  discount NUMERIC(10, 2)," +
417	                "  total NUMERIC(10, 2) NOT NULL," +
418	                "  status VARCHAR(20) NOT NULL," +
419	                "  amount_paid NUMERIC(10, 2) NOT NULL DEFAULT 0," +
420	                "  refund NUMERIC(10, 2)," +
421	                "  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP" +
422	                ")"
423	            );
424	
425	            // Create messages table
426	            conn.createStatement().execute(
427	                "CREATE TABLE IF NOT EXISTS messages (" +
428	                "  id BIGSERIAL PRIMARY KEY," +
429	                "  channel VARCHAR(20) NOT NULL," +
430	                "  to_address VARCHAR(255) NOT NULL," +
431	                "  subject VARCHAR(255) NOT NULL," +
432	                "  body TEXT NOT NULL," +
433	                "  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP" +
434	                ")"
435	            );
436	
437	            // Insert rooms if they don't exist
438	            conn.createStatement().execute(
439	                "INSERT INTO rooms (number, type, capacity, nightly_rate) " +
440	                "VALUES (101, 'STANDARD', 2, 249.90) " +
441	                "ON CONFLICT (number) DO NOTHING"
442	            );
443	            conn.createStatement().execute(
444	                "INSERT INTO rooms (number, type, capacity, nightly_rate) " +
445	                "VALUES (102, 'STANDARD', 2, 249.90) " +
446	                "ON CONFLICT (number) DO NOTHING"
447	            );
448	            conn.createStatement().execute(
449	                "INSERT INTO rooms (number, type, capacity, nightly_rate) " +
450	                "VALUES (201, 'DELUXE', 3, 389.90) " +
451	                "ON CONFLICT (number) DO NOTHING"
452	            );
453	            conn.createStatement().execute(
454	                "INSERT INTO rooms (number, type, capacity, nightly_rate) " +
455	                "VALUES (202, 'DELUXE', 3, 389.90) " +
456	                "ON CONFLICT (number) DO NOTHING"
457	            );
458	            conn.createStatement().execute(
459	                "INSERT INTO rooms (number, type, capacity, nightly_rate) " +
460	                "VALUES (301, 'SUITE', 4, 579.90) " +
461	                "ON CONFLICT (number) DO NOTHING"
462	            );
463	
464	            logger.info("Database tables initialized successfully");
465	        }
466	    }
467	}

