156	                sendError(ctx, 500, "DATABASE_ERROR", e.getMessage());
157	            } catch (Exception e) {
158	                sendError(ctx, 400, "INVALID_REQUEST", e.getMessage());
159	            }
160	        });
161	
162	        // POST /reservations/{id}/cancellation
163	        app.post("/reservations/{id}/cancellation", ctx -> {
