 15	public class DocumentService {
 16	
 17	    public static DocumentResponse generateDocument(Reservation reservation) throws SQLException {
 18	        DocumentResponse doc = new DocumentResponse();
 19	        doc.reservationId = reservation.getId();
 20	        doc.guestName = reservation.getGuestName();
 21	        doc.guestCpf = reservation.getGuestCpf();
 22	        doc.companyCnpj = reservation.getCompanyCnpj();
 23	        doc.companyName = reservation.getCompanyName();
 24	        doc.guestPassport = reservation.getGuestPassport();
 25	        doc.guestCountry = reservation.getGuestCountry();
 26	        doc.roomNumber = reservation.getRoomNumber();
 27	        doc.roomType = RoomRepository.findByNumber(reservation.getRoomNumber()).getType().name();
 28	        doc.checkIn = reservation.getCheckIn();
 29	        doc.checkOut = reservation.getCheckOut();
 30	        doc.nights = reservation.getNights();
 31	        doc.subtotal = reservation.getSubtotal();
 32	        doc.discount = reservation.getDiscount();
 33	        doc.total = reservation.getTotal();
 34	
 35	        if (reservation.getGuestCpf() != null) {
 36	            doc.title = "Comprovante de reserva";
 37	            doc.text = generateComprovante(reservation);
 38	        } else if (reservation.getCompanyCnpj() != null) {
 39	            doc.title = "Fatura de hospedagem";
 40	            doc.text = generateFatura(reservation);
 41	        } else {
 42	            doc.title = "Booking receipt";
 43	            doc.text = generateBookingReceipt(reservation);
 44	        }
 45	
 46	        return doc;
 47	    }
 48	
 49	    private static String generateComprovante(Reservation r) throws SQLException {
 50	        StringBuilder sb = new StringBuilder();
 51	        sb.append("Comprovante de reserva nº ").append(r.getId()).append("\n");
 52	        sb.append("Hóspede: ").append(r.getGuestName()).append(" (CPF ").append(r.getGuestCpf()).append(")\n");
 53	        sb.append("Quarto: ").append(r.getRoomNumber()).append(" (").append(
 54	            RoomRepository.findByNumber(r.getRoomNumber()).getType().name()).append(")\n");
 55	        sb.append("Entrada: ").append(formatDateBr(r.getCheckIn())).append(" | Saída: ")
 56	            .append(formatDateBr(r.getCheckOut())).append(" | ");
 57	        sb.append(r.getNights()).append(r.getNights() == 1 ? " diária" : " diárias").append("\n");
 58	        sb.append("Diárias: ").append(formatBrl(r.getSubtotal())).append("\n");
 59	
 60	        if (r.getDiscount() != null && r.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
 61	            sb.append("Desconto: ").append(formatBrl(r.getDiscount())).append("\n");
 62	        }
 63	
 64	        sb.append("Total: ").append(formatBrl(r.getTotal())).append("\n");
 65	
 66	        return sb.toString();
 67	    }
 68	
 69	    private static String generateFatura(Reservation r) throws SQLException {
 70	        StringBuilder sb = new StringBuilder();
 71	        sb.append("Fatura de hospedagem nº ").append(r.getId()).append("\n");
 72	        sb.append("Empresa: ").append(r.getCompanyName()).append(" (CNPJ ").append(r.getCompanyCnpj()).append(")\n");
 73	        sb.append("Hóspede: ").append(r.getGuestName()).append("\n");
 74	        sb.append("Quarto: ").append(r.getRoomNumber()).append(" (").append(
 75	            RoomRepository.findByNumber(r.getRoomNumber()).getType().name()).append(")\n");
 76	        sb.append("Entrada: ").append(formatDateBr(r.getCheckIn())).append(" | Saída: ")
 77	            .append(formatDateBr(r.getCheckOut())).append(" | ");
 78	        sb.append(r.getNights()).append(r.getNights() == 1 ? " diária" : " diárias").append("\n");
 79	        sb.append("Diárias: ").append(formatBrl(r.getSubtotal())).append("\n");
 80	
 81	        if (r.getDiscount() != null && r.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
 82	            sb.append("Desconto: ").append(formatBrl(r.getDiscount())).append("\n");
 83	        }
 84	
 85	        sb.append("Total: ").append(formatBrl(r.getTotal())).append("\n");
 86	
 87	        BigDecimal issRetention = PricingService.calculateIssRetention(r.getTotal());
 88	        sb.append("ISS retido (5%): ").append(formatBrl(issRetention)).append("\n");
 89	
 90	        return sb.toString();
 91	    }
 92	
 93	    private static String generateBookingReceipt(Reservation r) throws SQLException {
 94	        StringBuilder sb = new StringBuilder();
 95	        sb.append("Booking receipt no. ").append(r.getId()).append("\n");
 96	        sb.append("Guest: ").append(r.getGuestName()).append(" (passport ").append(r.getGuestPassport())
 97	            .append(", ").append(r.getGuestCountry()).append(")\n");
 98	        sb.append("Room: ").append(r.getRoomNumber()).append(" (").append(
 99	            RoomRepository.findByNumber(r.getRoomNumber()).getType().name()).append(")\n");
100	        sb.append("Check-in: ").append(formatDateEn(r.getCheckIn())).append(" | Check-out: ")
101	            .append(formatDateEn(r.getCheckOut())).append(" | ");
102	        sb.append(r.getNights()).append(r.getNights() == 1 ? " night" : " nights").append("\n");
103	        sb.append("Nights: ").append(formatUsd(r.getSubtotal())).append("\n");
104	
105	        if (r.getDiscount() != null && r.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
106	            sb.append("Discount: ").append(formatUsd(r.getDiscount())).append("\n");
107	        }
108	
109	        sb.append("Total: ").append(formatUsd(r.getTotal())).append("\n");
110	
111	        return sb.toString();
112	    }
