114	    private static String formatBrl(BigDecimal value) {
115	        DecimalFormatSymbols symbols = new DecimalFormatSymbols(new Locale("pt", "BR"));
116	        DecimalFormat df = new DecimalFormat("R$ #,##0.00", symbols);
117	        return df.format(value);
118	    }
119	
120	    private static String formatUsd(BigDecimal value) {
121	        DecimalFormatSymbols symbols = new DecimalFormatSymbols(Locale.US);
122	        DecimalFormat df = new DecimalFormat("BRL #,##0.00", symbols);
123	        return df.format(value);
124	    }
125	
126	    private static String formatDateBr(LocalDate date) {
127	        return date.format(DateTimeFormatter.ofPattern("dd/MM/yyyy"));
128	    }
129	
130	    private static String formatDateEn(LocalDate date) {
131	        return date.format(DateTimeFormatter.ofPattern("yyyy-MM-dd"));
132	    }
133	}
