171	import java.math.BigDecimal;
172	import java.math.RoundingMode;
173	import java.time.LocalDate;
174	import java.time.YearMonth;
175	
176	public class PricingService {
177	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = BigDecimal.valueOf(1.20);
178	    private static final BigDecimal DISCOUNT_RATE = BigDecimal.valueOf(0.15);
179	    private static final BigDecimal ISS_RATE = BigDecimal.valueOf(0.05);
180	
181	    public static BigDecimal calculateNightlyPrice(BigDecimal baseRate, LocalDate date) {
182	        if (isHighSeason(date)) {
183	            return baseRate.multiply(HIGH_SEASON_MULTIPLIER).setScale(2, RoundingMode.HALF_EVEN);
184	        }
185	        return baseRate.setScale(2, RoundingMode.HALF_EVEN);
186	    }
187	
188	    public static BigDecimal calculateSubtotal(BigDecimal baseRate, LocalDate checkIn, LocalDate checkOut) {
189	        BigDecimal subtotal = BigDecimal.ZERO;
190	        LocalDate current = checkIn;
191	        while (current.isBefore(checkOut)) {
192	            subtotal = subtotal.add(calculateNightlyPrice(baseRate, current));
193	            current = current.plusDays(1);
194	        }
195	        return subtotal.setScale(2, RoundingMode.HALF_EVEN);
196	    }
197	
198	    public static BigDecimal calculateDiscount(BigDecimal subtotal, boolean isNonRefundable) {
199	        if (isNonRefundable) {
200	            return subtotal.multiply(DISCOUNT_RATE).setScale(2, RoundingMode.HALF_EVEN);
201	        }
202	        return BigDecimal.ZERO.setScale(2, RoundingMode.HALF_EVEN);
