434	    public static Reservation confirmReservation(long reservationId, BigDecimal amountPaid) throws SQLException {
435	        Reservation reservation = ReservationRepository.findById(reservationId);
436	        if (reservation == null) {
437	            throw new IllegalArgumentException("RESERVATION_NOT_FOUND");
438	        }
439	
440	        if (reservation.getStatus() != Reservation.Status.PENDING) {
441	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
442	        }
443	
444	        reservation.setStatus(Reservation.Status.CONFIRMED);
445	        reservation.setAmountPaid(amountPaid);
446	        ReservationRepository.update(reservation);
447	
448	        // Send confirmation email
449	        MessageService.sendConfirmationEmail(reservation);
450	
451	        return reservation;
452	    }
