454	    public static Reservation cancelReservation(long reservationId) throws SQLException {
455	        Reservation reservation = ReservationRepository.findById(reservationId);
456	        if (reservation == null) {
457	            throw new IllegalArgumentException("RESERVATION_NOT_FOUND");
458	        }
459	
460	        if (reservation.getStatus() != Reservation.Status.PENDING &&
461	            reservation.getStatus() != Reservation.Status.CONFIRMED) {
462	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
463	        }
464	
465	        BigDecimal refundAmount = BigDecimal.ZERO;
466	        if (reservation.getStatus() == Reservation.Status.CONFIRMED &&
467	            reservation.getRatePlan() == Reservation.RatePlan.STANDARD) {
468	            refundAmount = reservation.getAmountPaid();
469	        }
470	
471	        reservation.setStatus(Reservation.Status.CANCELLED);
472	        reservation.setRefund(refundAmount);
473	        ReservationRepository.update(reservation);
474	
475	        return reservation;
476	    }
