262	            "AND r.check_in <= ? " +
263	            "AND r.check_out > ? " +
264	            "ORDER BY r.room_number, r.id";
265	
266	        int occupiedRooms = 0;
267	        try (Connection conn = DatabaseConfig.getConnection()) {
268	            PreparedStatement stmt = conn.prepareStatement(sql);
269	            stmt.setObject(1, date);
270	            stmt.setObject(2, date);
271	            ResultSet rs = stmt.executeQuery();
272	
273	            while (rs.next()) {
274	                long reservationId = rs.getLong("id");
275	                int roomNumber = rs.getInt("room_number");
276	                LocalDate checkIn = rs.getObject("check_in", LocalDate.class);
277	                LocalDate checkOut = rs.getObject("check_out", LocalDate.class);
278	
279	                String roomType = RoomRepository.findByNumber(roomNumber).getType().name();
280	                csv.append(roomNumber).append(",")
281	                    .append(roomType).append(",")
282	                    .append(reservationId).append(",")
283	                    .append(checkIn).append(",")
284	                    .append(checkOut).append("\n");
285	
286	                occupiedRooms++;
287	            }
288	        }
289	
290	        csv.append("total,").append(occupiedRooms).append("/5\n");
291	        return csv.toString();
292	    }
293	
294	    public static String getRevenueReport(YearMonth month) throws SQLException {
295	        StringBuilder csv = new StringBuilder();
296	        csv.append("reservation,room,check_in,check_out,status,amount\n");
297	
298	        String sql = "SELECT r.id, r.room_number, r.check_in, r.check_out, r.status, " +
299	            "r.amount_paid, r.refund " +
300	            "FROM reservations r " +
301	            "WHERE EXTRACT(YEAR FROM r.check_in) = ? " +
302	            "AND EXTRACT(MONTH FROM r.check_in) = ? " +
303	            "AND (r.amount_paid > 0 OR r.refund > 0) " +
304	            "AND r.status IN ('CONFIRMED', 'CHECKED_IN', 'CHECKED_OUT', 'CANCELLED') " +
305	            "ORDER BY r.check_in, r.id";
306	
307	        BigDecimal totalAmount = BigDecimal.ZERO;
308	        try (Connection conn = DatabaseConfig.getConnection()) {
309	            PreparedStatement stmt = conn.prepareStatement(sql);
310	            stmt.setInt(1, month.getYear());
311	            stmt.setInt(2, month.getMonthValue());
312	            ResultSet rs = stmt.executeQuery();
313	
314	            while (rs.next()) {
315	                long reservationId = rs.getLong("id");
316	                int roomNumber = rs.getInt("room_number");
317	                LocalDate checkIn = rs.getObject("check_in", LocalDate.class);
318	                LocalDate checkOut = rs.getObject("check_out", LocalDate.class);
319	                String status = rs.getString("status");
320	                BigDecimal amountPaid = rs.getBigDecimal("amount_paid");
321	                BigDecimal refund = rs.getBigDecimal("refund");
322	
323	                BigDecimal netAmount = amountPaid.subtract(refund == null ? BigDecimal.ZERO : refund);
324	
325	                csv.append(reservationId).append(",")
326	                    .append(roomNumber).append(",")
327	                    .append(checkIn).append(",")
328	                    .append(checkOut).append(",")
329	                    .append(status).append(",")
330	                    .append(formatAmount(netAmount)).append("\n");
331	
332	                totalAmount = totalAmount.add(netAmount);
333	            }
334	        }
335	
336	        csv.append("total,").append(formatAmount(totalAmount)).append("\n");
337	        return csv.toString();
338	    }
339	
340	    private static String formatAmount(BigDecimal amount) {
341	        return amount.toPlainString();
342	    }
343	}
