346	import com.pousada.marealta.model.Reservation;
347	import com.pousada.marealta.model.Room;
348	import com.pousada.marealta.repository.ReservationRepository;
349	import com.pousada.marealta.repository.RoomRepository;
350	
351	import java.math.BigDecimal;
352	import java.sql.SQLException;
353	import java.time.LocalDate;
354	
355	public class ReservationService {
356	
357	    public static Reservation getReservation(long reservationId) throws SQLException {
358	        return ReservationRepository.findById(reservationId);
359	    }
360	
361	    public static Reservation createReservation(int roomNumber, String guestName, String guestEmail,
362	                                               LocalDate checkIn, LocalDate checkOut, int guests,
363	                                               String ratePlanStr, String guestCpf, String companyCnpj,
364	                                               String companyName, String guestPassport, String guestCountry)
365	            throws SQLException {
366	
367	        // Validate room exists
368	        Room room = RoomRepository.findByNumber(roomNumber);
369	        if (room == null) {
370	            throw new IllegalArgumentException("ROOM_NOT_FOUND");
371	        }
372	
373	        // Validate dates
374	        if (checkOut.isBefore(checkIn) || checkOut.equals(checkIn)) {
375	            throw new IllegalArgumentException("INVALID_REQUEST");
376	        }
377	
378	        // Validate guests
379	        if (guests < 1) {
380	            throw new IllegalArgumentException("INVALID_REQUEST");
381	        }
382	        if (guests > room.getCapacity()) {
383	            throw new IllegalArgumentException("CAPACITY_EXCEEDED");
384	        }
385	
386	        // Validate identification
387	        int identificationCount = 0;
388	        if (guestCpf != null) identificationCount++;
389	        if (companyCnpj != null) identificationCount++;
390	        if (guestPassport != null) identificationCount++;
391	        if (identificationCount != 1) {
392	            throw new IllegalArgumentException("INVALID_REQUEST");
393	        }
394	
395	        // Check room availability
396	        if (!ReservationRepository.isRoomAvailable(roomNumber, checkIn, checkOut)) {
397	            throw new IllegalArgumentException("ROOM_UNAVAILABLE");
398	        }
399	
400	        // Parse rate plan
401	        Reservation.RatePlan ratePlan;
402	        try {
403	            ratePlan = Reservation.RatePlan.valueOf(ratePlanStr);
404	        } catch (IllegalArgumentException e) {
405	            throw new IllegalArgumentException("INVALID_REQUEST");
406	        }
407	
408	        // Create reservation
409	        Reservation reservation = new Reservation(roomNumber, guestName, guestEmail, checkIn, checkOut, guests, ratePlan);
410	        reservation.setGuestCpf(guestCpf);
411	        reservation.setCompanyCnpj(companyCnpj);
412	        reservation.setCompanyName(companyName);
413	        reservation.setGuestPassport(guestPassport);
414	        reservation.setGuestCountry(guestCountry);
415	
416	        // Calculate prices
417	        int nights = PricingService.calculateNights(checkIn, checkOut);
418	        reservation.setNights(nights);
419	
420	        BigDecimal subtotal = PricingService.calculateSubtotal(room.getNightlyRate(), checkIn, checkOut);
421	        reservation.setSubtotal(subtotal);
422	
423	        boolean isNonRefundable = ratePlan == Reservation.RatePlan.NON_REFUNDABLE;
424	        BigDecimal discount = PricingService.calculateDiscount(subtotal, isNonRefundable);
425	        reservation.setDiscount(discount);
426	
427	        BigDecimal total = PricingService.calculateTotal(subtotal, discount);
428	        reservation.setTotal(total);
429	
430	        // Save to database
431	        return ReservationRepository.create(reservation);
432	    }
433	
434	    public static Reservation confirmReservation(long reservationId, BigDecimal amountPaid) throws SQLException {
435	        Reservation reservation = ReservationRepository.findById(reservationId);
436	        if (reservation == null) {
437	            throw new IllegalArgumentException("RESERVATION_NOT_FOUND");
438	        }
439	
440	        if (reservation.getStatus() != Reservation.Status.PENDING) {
441	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
442	        }
443	
444	        reservation.setStatus(Reservation.Status.CONFIRMED);
445	        reservation.setAmountPaid(amountPaid);
446	        ReservationRepository.update(reservation);
447	
448	        // Send confirmation email
449	        MessageService.sendConfirmationEmail(reservation);
450	
451	        return reservation;
452	    }
453	
454	    public static Reservation cancelReservation(long reservationId) throws SQLException {
455	        Reservation reservation = ReservationRepository.findById(reservationId);
456	        if (reservation == null) {
457	            throw new IllegalArgumentException("RESERVATION_NOT_FOUND");
458	        }
459	
460	        if (reservation.getStatus() != Reservation.Status.PENDING &&
461	            reservation.getStatus() != Reservation.Status.CONFIRMED) {
462	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
463	        }
464	
465	        BigDecimal refundAmount = BigDecimal.ZERO;
466	        if (reservation.getStatus() == Reservation.Status.CONFIRMED &&
467	            reservation.getRatePlan() == Reservation.RatePlan.STANDARD) {
468	            refundAmount = reservation.getAmountPaid();
469	        }
470	
471	        reservation.setStatus(Reservation.Status.CANCELLED);
472	        reservation.setRefund(refundAmount);
473	        ReservationRepository.update(reservation);
474	
475	        return reservation;
476	    }
477	
478	    public static Reservation checkIn(long reservationId) throws SQLException {
479	        Reservation reservation = ReservationRepository.findById(reservationId);
480	        if (reservation == null) {
481	            throw new IllegalArgumentException("RESERVATION_NOT_FOUND");
482	        }
483	
484	        if (reservation.getStatus() != Reservation.Status.CONFIRMED) {
485	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
486	        }
487	
488	        reservation.setStatus(Reservation.Status.CHECKED_IN);
489	        ReservationRepository.update(reservation);
490	
491	        return reservation;
492	    }
493	
494	    public static Reservation checkOut(long reservationId) throws SQLException {
495	        Reservation reservation = ReservationRepository.findById(reservationId);
496	        if (reservation == null) {
497	            throw new IllegalArgumentException("RESERVATION_NOT_FOUND");
498	        }
499	
500	        if (reservation.getStatus() != Reservation.Status.CHECKED_IN) {
501	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
502	        }
503	
504	        reservation.setStatus(Reservation.Status.CHECKED_OUT);
505	        ReservationRepository.update(reservation);
506	
507	        return reservation;
508	    }
509	}

