442	    public static void update(Reservation reservation) throws SQLException {
443	        String sql = "UPDATE reservations SET status = ?, amount_paid = ?, refund = ? WHERE id = ?";
444	
445	        try (Connection conn = DatabaseConfig.getConnection()) {
446	            PreparedStatement stmt = conn.prepareStatement(sql);
447	            stmt.setString(1, reservation.getStatus().name());
448	            stmt.setBigDecimal(2, reservation.getAmountPaid());
449	            stmt.setBigDecimal(3, reservation.getRefund());
