517	    private static final Logger logger = LoggerFactory.getLogger(RoomRepository.class);
518	
519	    public static List<Room> findAll() throws SQLException {
520	        List<Room> rooms = new ArrayList<>();
521	        try (Connection conn = DatabaseConfig.getConnection()) {
522	            var stmt = conn.createStatement();
523	            ResultSet rs = stmt.executeQuery("SELECT number, type, capacity, nightly_rate FROM rooms ORDER BY number");
524	            while (rs.next()) {
525	                Room room = new Room(
526	                    rs.getInt("number"),
527	                    Room.Type.valueOf(rs.getString("type")),
528	                    rs.getInt("capacity"),
529	                    rs.getBigDecimal("nightly_rate")
530	                );
531	                rooms.add(room);
532	            }
533	        }
534	        return rooms;
535	    }
536	
537	    public static Room findByNumber(int number) throws SQLException {
538	        try (Connection conn = DatabaseConfig.getConnection()) {
539	            var stmt = conn.prepareStatement("SELECT number, type, capacity, nightly_rate FROM rooms WHERE number = ?");
540	            stmt.setInt(1, number);
541	            ResultSet rs = stmt.executeQuery();
542	            if (rs.next()) {
543	                return new Room(
544	                    rs.getInt("number"),
545	                    Room.Type.valueOf(rs.getString("type")),
546	                    rs.getInt("capacity"),
547	                    rs.getBigDecimal("nightly_rate")
548	                );
549	            }
550	        }
551	        return null;
552	    }
553	}
