  2	
  3	import com.pousada.marealta.model.Reservation;
  4	import com.pousada.marealta.service.PricingService;
  5	import org.junit.jupiter.api.Test;
  6	
  7	import java.math.BigDecimal;
  8	import java.math.RoundingMode;
  9	import java.time.LocalDate;
 10	
 11	import static org.junit.jupiter.api.Assertions.*;
 12	
 13	public class ReservationIntegrationTest {
 14	
 15	    @Test
 16	    public void testHighSeasonPricing() {
 17	        // July 10-12, 2027 (high season)
 18	        LocalDate checkIn = LocalDate.of(2027, 7, 10);
 19	        LocalDate checkOut = LocalDate.of(2027, 7, 12);
 20	
 21	        // STANDARD room: R$ 249.90
 22	        BigDecimal baseRate = new BigDecimal("249.90");
 23	        BigDecimal subtotal = PricingService.calculateSubtotal(baseRate, checkIn, checkOut);
 24	
 25	        // Each night costs 249.90 * 1.20 = 299.88
 26	        // 2 nights: 299.88 * 2 = 599.76
 27	        assertEquals(new BigDecimal("599.76"), subtotal);
 28	    }
 29	
 30	    @Test
 31	    public void testNonHighSeasonPricing() {
 32	        // March 10-12, 2027 (not high season)
 33	        LocalDate checkIn = LocalDate.of(2027, 3, 10);
 34	        LocalDate checkOut = LocalDate.of(2027, 3, 12);
 35	
 36	        BigDecimal baseRate = new BigDecimal("389.90");
 37	        BigDecimal subtotal = PricingService.calculateSubtotal(baseRate, checkIn, checkOut);
 38	
 39	        // Each night costs 389.90
 40	        // 2 nights: 389.90 * 2 = 779.80
 41	        assertEquals(new BigDecimal("779.80"), subtotal);
 42	    }
 43	
 44	    @Test
 45	    public void testNonRefundableDiscount() {
 46	        BigDecimal subtotal = new BigDecimal("599.76");
 47	        BigDecimal discount = PricingService.calculateDiscount(subtotal, true);
 48	
 49	        // 15% discount: 599.76 * 0.15 = 89.964 -> 89.96 (banker's rounding)
 50	        assertEquals(new BigDecimal("89.96"), discount);
 51	
 52	        BigDecimal total = PricingService.calculateTotal(subtotal, discount);
 53	        assertEquals(new BigDecimal("509.80"), total);
 54	    }
 55	
 56	    @Test
 57	    public void testStandardRateNoDiscount() {
 58	        BigDecimal subtotal = new BigDecimal("779.80");
 59	        BigDecimal discount = PricingService.calculateDiscount(subtotal, false);
 60	
 61	        assertEquals(BigDecimal.ZERO.setScale(2, RoundingMode.HALF_EVEN), discount);
 62	
 63	        BigDecimal total = PricingService.calculateTotal(subtotal, discount);
 64	        assertEquals(new BigDecimal("779.80"), total);
 65	    }
 66	
 67	    @Test
 68	    public void testDecemberHighSeason() {
 69	        // December 20, 2027 (high season starts from Dec 15)
 70	        LocalDate date = LocalDate.of(2027, 12, 20);
 71	        BigDecimal baseRate = new BigDecimal("249.90");
 72	        BigDecimal nightPrice = PricingService.calculateNightlyPrice(baseRate, date);
 73	
 74	        // 249.90 * 1.20 = 299.88
 75	        assertEquals(new BigDecimal("299.88"), nightPrice);
 76	    }
 77	
 78	    @Test
 79	    public void testFebruaryHighSeason() {
 80	        // February 15, 2027 (high season)
 81	        LocalDate date = LocalDate.of(2027, 2, 15);
 82	        BigDecimal baseRate = new BigDecimal("389.90");
 83	        BigDecimal nightPrice = PricingService.calculateNightlyPrice(baseRate, date);
 84	
 85	        // 389.90 * 1.20 = 467.88
 86	        assertEquals(new BigDecimal("467.88"), nightPrice);
 87	    }
 88	
 89	    @Test
 90	    public void testNightCount() {
 91	        LocalDate checkIn = LocalDate.of(2027, 7, 10);
 92	        LocalDate checkOut = LocalDate.of(2027, 7, 12);
 93	        int nights = PricingService.calculateNights(checkIn, checkOut);
 94	        assertEquals(2, nights);
 95	    }
 96	
 97	    @Test
 98	    public void testIssRetention() {
 99	        BigDecimal total = new BigDecimal("779.80");
100	        BigDecimal iss = PricingService.calculateIssRetention(total);
101	
102	        // 5% of 779.80 = 38.99
103	        assertEquals(new BigDecimal("38.99"), iss);
104	    }
105	
106	    @Test
107	    public void testBankerRounding() {
108	        // Test round half even - rounds to even number
109	        BigDecimal value = new BigDecimal("89.964");
110	        BigDecimal rounded = value.setScale(2, RoundingMode.HALF_EVEN);
111	        assertEquals(new BigDecimal("89.96"), rounded);
112	
113	        // Test round half even - 89.965 rounds to 89.96 (even) not 89.97 (odd)
114	        BigDecimal value2 = new BigDecimal("89.965");
115	        BigDecimal rounded2 = value2.setScale(2, RoundingMode.HALF_EVEN);
116	        assertEquals(new BigDecimal("89.96"), rounded2);
117	
118	        // Test round half even - 89.975 rounds to 89.98 (even)
119	        BigDecimal value3 = new BigDecimal("89.975");
120	        BigDecimal rounded3 = value3.setScale(2, RoundingMode.HALF_EVEN);
121	        assertEquals(new BigDecimal("89.98"), rounded3);
122	    }
123	}

